var _markdown = "\n\n## Simple Example [#simple-example]\n\n```tsx\nimport React from 'react';\nimport { View } from 'react-native';\nimport { PaymentIcon } from 'react-native-payment-card-icons';\n\nexport default function App() {\n  return (\n    <View>\n      <PaymentIcon type=\"visa\" />\n    </View>\n  );\n}\n```\n\n## With Custom Styling [#with-custom-styling]\n\n```tsx\nimport React from 'react';\nimport { View } from 'react-native';\nimport { PaymentIcon } from 'react-native-payment-card-icons';\n\nexport default function StyledIcons() {\n  return (\n    <View>\n      {/* Custom size */}\n      <PaymentIcon\n        type=\"mastercard\"\n        width={60}\n        height={40}\n      />\n\n      {/* Custom variant */}\n      <PaymentIcon\n        type=\"amex\"\n        variant=\"flatRounded\"\n        width={60}\n        height={40}\n      />\n\n      {/* Monochrome with custom color */}\n      <PaymentIcon\n        type=\"discover\"\n        variant=\"mono\"\n        width={60}\n        height={40}\n        fill=\"#007bff\"\n      />\n    </View>\n  );\n}\n```\n\n## Using Individual Icons [#using-individual-icons]\n\nYou can also import specific icons directly:\n\n```tsx\nimport React from 'react';\nimport { View } from 'react-native';\nimport {\n  VisaFlat,\n  MastercardLogo,\n  AmexMono\n} from 'react-native-payment-card-icons';\n\nexport default function DirectImports() {\n  return (\n    <View>\n      <VisaFlat width={60} height={40} />\n      <MastercardLogo width={60} height={40} />\n      <AmexMono width={60} height={40} fill=\"#333\" />\n    </View>\n  );\n}\n```\n\n## In a Payment Form [#in-a-payment-form]\n\n```tsx\nimport React, { useState } from 'react';\nimport { View, TextInput, StyleSheet } from 'react-native';\nimport { PaymentIcon } from 'react-native-payment-card-icons';\n\n// Simple card type detection\nconst detectCardType = (number: string) => {\n  if (number.startsWith('4')) return 'visa';\n  if (number.startsWith('5')) return 'mastercard';\n  if (number.startsWith('3')) return 'amex';\n  return 'generic-card';\n};\n\nexport default function PaymentForm() {\n  const [cardNumber, setCardNumber] = useState('');\n  const cardType = detectCardType(cardNumber);\n\n  return (\n    <View style={styles.container}>\n      <View style={styles.inputContainer}>\n        <TextInput\n          style={styles.input}\n          placeholder=\"Card Number\"\n          value={cardNumber}\n          onChangeText={setCardNumber}\n          keyboardType=\"numeric\"\n        />\n        <PaymentIcon\n          type={cardType}\n          variant=\"flat\"\n          width={40}\n          height={25}\n        />\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: {\n    padding: 20,\n  },\n  inputContainer: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    borderWidth: 1,\n    borderColor: '#ddd',\n    borderRadius: 8,\n    paddingHorizontal: 15,\n  },\n  input: {\n    flex: 1,\n    height: 50,\n    fontSize: 16,\n  },\n});\n```\n";
